optimization-iteration.patch:
diff --git a/scripts/bot-evaluation/host-evidence.ts b/scripts/bot-evaluation/host-evidence.ts
index afc381fa..1765e1e4 100644
--- a/scripts/bot-evaluation/host-evidence.ts
+++ b/scripts/bot-evaluation/host-evidence.ts
@@ -172,7 +172,7 @@ export function changes(
           value: p[key],
         });
   }
-  if (JSON.stringify(before.chain) !== JSON.stringify(after.chain))
+  if (before.chain !== after.chain && JSON.stringify(before.chain) !== JSON.stringify(after.chain))
     out.push({ type: "chain_changed", chain: record(after.chain) });
   return out;
 }
